JsAppErrorEvent _error({String message = 'boom', String fingerprint = ''}) =>
    JsAppErrorEvent(
      kind: JsAppErrorKind.callback,
      message: message,
      stack: 'at widget.js:7:3',
      fingerprint: fingerprint,
    );

