          '"stack":"at f ({a:1})\\n","fingerprint":"bad {token}#"}';
      final event = parseJsAppErrorLogLine('{id: [E] faAppError:$nested}');
      expect(event, isNotNull);
      expect(event!.kind, JsAppErrorKind.callback);
      expect(event.message, contains('{token}'));
