  late JsAppErrorChannel channel;

  setUp(() => channel = JsAppErrorChannel.test());

  JsAppErrorFeedback? report(
    JsAppErrorChannel target,
    JsAppErrorEvent event, {
    String revision = 'r1',
  }) => target.reportAppError(
    event,
